package app.noir.mobile;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
import java.time.*;
public final class SmartListsTest {
 final long now=Instant.parse("2026-10-25T12:00:00Z").toEpochMilli();
 SmartLists.Episode ep(int e,boolean watched,int count,int rating,long at,double minutes,boolean play,long air){return new SmartLists.Episode("e"+e,1,e,watched,false,count,rating,at,minutes,play,air,"Summary "+e);}
 SmartLists.Title title(boolean movie,boolean dropped,SmartLists.Episode... eps){return new SmartLists.Title("show",movie,dropped,Arrays.asList(eps),Collections.emptyList());}
 int count(SmartLists.Title title,String row){return SmartLists.build(Arrays.asList(title),now,false).get(row).size();}
 @Test public void unfinishedThresholdAvailabilityAndDropped(){SmartLists.Episode seen=ep(1,true,1,0,now-14*SmartLists.DAY,24,true,0),next=ep(2,false,0,0,0,24,false,now-SmartLists.DAY);assertEquals(1,count(title(false,false,seen,next),"unfinished"));assertEquals(0,count(title(false,true,seen,next),"unfinished"));seen.lastViewed++;assertEquals(0,count(title(false,false,seen,next),"unfinished"));seen.lastViewed--;next.airsAt=0;assertEquals(0,count(title(false,false,seen,next),"unfinished"));next.playable=true;assertEquals(1,count(title(false,false,seen,next),"unfinished"));next.airsAt=now+1;assertEquals(0,count(title(false,false,seen,next),"unfinished"));}
 @Test public void nextFollowsProgressRatherThanOlderUnmarkedGaps(){SmartLists.Episode partial=ep(4,false,0,0,now-21*SmartLists.DAY,24,true,0);partial.started=true;SmartLists.Title show=title(false,false,ep(1,false,0,0,0,24,true,0),partial,ep(5,false,0,0,0,24,true,0));assertEquals("e4",SmartLists.build(Arrays.asList(show),now,false).get("unfinished").get(0).episodeId);partial.started=false;partial.watched=true;assertEquals("e5",SmartLists.build(Arrays.asList(show),now,false).get("unfinished").get(0).episodeId);}
 @Test public void comfortCountsTitleWatchesAndCalendarMonths(){assertEquals(1,count(title(true,false,ep(1,true,2,0,now,90,true,0)),"comfort"));assertEquals(0,count(title(false,false,ep(1,true,1,0,now,24,true,0),ep(2,true,1,0,now,24,true,0)),"comfort"));long six=Instant.ofEpochMilli(now).atZone(ZoneOffset.UTC).minusMonths(6).toInstant().toEpochMilli();SmartLists.Episode movie=ep(1,true,1,9,six,90,true,0);assertEquals(1,count(title(true,false,movie),"comfort"));movie.lastViewed++;assertEquals(0,count(title(true,false,movie),"comfort"));movie.lastViewed--;movie.rating10=8;assertEquals(0,count(title(true,false,movie),"comfort"));}
 @Test public void directorsRequireTwoDistinctRatedTitlesAndCache(){SmartLists.Title one=title(true,false,ep(1,true,1,8,now,90,true,0)),two=title(true,false,ep(1,true,1,8,now,90,true,0));one.directors=Arrays.asList("Director","Director");two.directors=Arrays.asList("DIRECTOR");two.key="two";assertEquals(2,SmartLists.build(Arrays.asList(one,two),now,false).get("directors").size());two.episodes.get(0).rating10=7;assertTrue(SmartLists.build(Arrays.asList(one,two),now,false).get("directors").isEmpty());one.directors=Collections.emptyList();two.directors=Collections.emptyList();assertTrue(SmartLists.build(Arrays.asList(one,two),now,false).get("directors").isEmpty());}
 @Test public void shortTonightStrictRuntimeAndPlayback(){SmartLists.Episode movie=ep(1,false,0,0,0,99.9,true,0);assertEquals(1,count(title(true,false,movie),"short-tonight"));movie.minutes=100;assertEquals(0,count(title(true,false,movie),"short-tonight"));movie.minutes=29.9;assertEquals(1,count(title(false,false,movie),"short-tonight"));movie.minutes=30;assertEquals(0,count(title(false,false,movie),"short-tonight"));movie.minutes=0;assertEquals(0,count(title(false,false,movie),"short-tonight"));movie.minutes=24;movie.playable=false;assertEquals(0,count(title(false,false,movie),"short-tonight"));movie.playable=true;movie.airsAt=now+1;assertEquals(0,count(title(false,false,movie),"short-tonight"));}
 @Test public void recapStopsAtProgressAndDismissesOnlyThisReturn(){SmartLists.Episode first=ep(1,true,1,0,now-18*SmartLists.DAY,24,true,0),second=ep(2,true,1,0,now-17*SmartLists.DAY,24,true,0),partial=ep(3,false,0,0,now-14*SmartLists.DAY,24,true,0),later=ep(4,true,1,0,now-30*SmartLists.DAY,24,true,0);partial.started=true;SmartLists.Title show=title(false,false,first,second,partial,later);PhoneCatchUp.Recap recap=PhoneCatchUp.build(show,now,14,"");assertNotNull(recap);assertEquals(2,recap.episodes.size());assertEquals(2,recap.episodes.get(1).episode);assertNull(PhoneCatchUp.build(show,now,14,recap.returnId));assertNull(PhoneCatchUp.build(show,now,15,""));assertNull(PhoneCatchUp.build(show,now,0,""));partial.lastViewed=now;assertNull(PhoneCatchUp.build(show,now,14,recap.returnId));assertNotNull(PhoneCatchUp.build(show,now+14*SmartLists.DAY,14,recap.returnId));}
 @Test public void settingsAndDismissalsPersistInTheProfile()throws Exception{android.content.Context real=androidx.test.platform.app.InstrumentationRegistry.getInstrumentation().getTargetContext();java.io.File directory=new java.io.File(real.getFilesDir(),"smart-lists-"+UUID.randomUUID());directory.mkdirs();android.content.Context isolated=new android.content.ContextWrapper(real){@Override public android.content.Context getApplicationContext(){return this;}@Override public java.io.File getFilesDir(){return directory;}@Override public java.io.File getCacheDir(){java.io.File cache=new java.io.File(directory,"cache");cache.mkdirs();return cache;}};DataStore data=new DataStore(isolated);try{PhoneCatchUp.setThresholdDays(data,30);data.pref(PhoneCatchUp.dismissKey("show"),"return-one");data.flush();DataStore restored=new DataStore(isolated);try{assertEquals(30,PhoneCatchUp.getThresholdDays(restored));assertEquals("return-one",restored.prefs().optString(PhoneCatchUp.dismissKey("show")));PhoneCatchUp.setThresholdDays(restored,0);assertEquals(0,PhoneCatchUp.getThresholdDays(restored));assertTrue(PhoneCatchUp.directors(new org.json.JSONObject().put("cast",new org.json.JSONArray().put("Actor"))).isEmpty());assertEquals(Arrays.asList("Director"),PhoneCatchUp.directors(new org.json.JSONObject().put("director",new org.json.JSONArray().put("Director"))));}finally{restored.network.shutdownNow();restored.images.shutdownNow();}}finally{data.network.shutdownNow();data.images.shutdownNow();}}
 @Test public void streamEligibilityRequiresRecentConfirmationInThisProfile(){SmartLists.rememberStream("profile","item",true,now);assertTrue(SmartLists.streamReady("profile","item",now));assertFalse(SmartLists.streamReady("other","item",now));assertFalse(SmartLists.streamReady("profile","item",now+1800001));SmartLists.rememberStream("profile","item",false,now);assertFalse(SmartLists.streamReady("profile","item",now));}
 @Test public void arabicStringsRemainArabic(){PhoneCatchUp.init();assertEquals("ذكّرني بالأحداث",Loc.AR.get("Catch me up"));assertTrue(SmartLists.ago(now-21*SmartLists.DAY,now,true).contains("قبل"));SmartLists.Title shortTitle=title(true,false,ep(1,false,0,0,0,90,true,0));assertTrue(SmartLists.build(Arrays.asList(shortTitle),now,true).get("short-tonight").get(0).reason.contains("جاهز للمشاهدة"));}
 @Test public void elevenThousandTitlesOnePass(){List<SmartLists.Title> titles=new ArrayList<>();for(int n=0;n<11000;n++){SmartLists.Title title=title(true,false,ep(1,false,0,0,0,90,true,0));title.key="m"+n;titles.add(title);}assertEquals(11000,SmartLists.build(titles,now,false).get("short-tonight").size());}
}
